def bbox_cells(cells):
    """(top, left) and the set of cells of a component, for mask extraction."""
    top = min(r for r, c in cells); left = min(c for r, c in cells)
    return top, left, set(cells)

def mask3(cells, top, left):
    """The 3x3 binary mask of a component whose bounding box starts at (top, left)."""
    return tuple(tuple(1 if (r, c) in cells else 0 for c in range(left, left + 3)) for r in range(top, top + 3))

def snake(grid, rules, order_key=None):
    """Draw each left-panel shape as a straight segment (direction, length from `rules` keyed by 3x3 mask), chaining segments into a snake starting one row below the 5 marker; blocks ordered by (left, top) unless order_key given."""
    h, w = len(grid), len(grid[0])
    div = next(j for j in range(w) if all(row[j] == 4 for row in grid))
    five = [(i, j) for i in range(h) for j in range(div + 1, w) if grid[i][j] == 5][0]
    blocks = []
    for color, cells in components8(grid, div):
        top, left, cs = bbox_cells(cells)
        d, l = rules[mask3(cs, top, left)]
        blocks.append((left, top, color, d, l))
    blocks.sort(key=order_key)
    out = [[0] * div for _ in range(h)]
    out[five[0]][five[1] - (div + 1)] = 5
    r, c = five[0] + 1, five[1] - (div + 1)
